const rawOutput = String($input.first().json.output || '').trim();
const trigger = $('When WhatsApp Message Arrives').first().json;
const settings = $('Configure Agent Settings').first().json;
const needsEscalation = rawOutput.includes('[ESCALATE]');
const cleanReply = rawOutput.replace(/\[ESCALATE\]\s*/g, '').trim() || 'Thanks for reaching out! A teammate will follow up shortly.';
const groupTarget = String(settings.escalationGroupChatId || '').trim();
const shouldNotifyGroup = needsEscalation && groupTarget !== '' && groupTarget !== 'YOUR_ESCALATION_GROUP_ID@g.us';

return [{
  json: {
    chatId: trigger.chat.id,
    senderName: trigger.author?.username || trigger.chat?.title || trigger.chat.id,
    customerMessage: trigger.text,
    quotedMessageId: trigger.messageId || '',
    cleanReply,
    needsEscalation,
    shouldNotifyGroup,
    escalationGroupChatId: groupTarget,
  },
}];
